('1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'အဆင့်မြင့် အသက်မွေးဝမ်းကျောင်း ဖွံ့ဖြိုးရေးသင်တန်း', 'Advanced Livelihood Development Course', 'စီးပွားရေးစီမံမှု၊ ဈေးကွက်ချိတ်ဆက်မှုနှင့် ရေရှည်အသက်မွေးဝမ်းကျောင်းဖွံ့ဖြိုးမှု။', 'Business management, market linkages and sustainable livelihood development.', 'ADVANCED', 2, true, '2026-11-03 15:12:28.480993+00'),
('7f377790-81fe-4b86-bed5-0ea8e1990586', 'အခြေခံ အသက်မွေးဝမ်းကျောင်း သင်တန်း', 'Basic Livelihood Course', 'ဘဝကျွမ်းကျင်မှု၊ အခြေခံအသက်မွေးဝမ်းကျောင်းကျွမ်းကျင်မှုနှင့် ငွေကြေးအသိပညာ။', 'Life skills, foundational vocational skills and basic financial literacy.', 'BASIC', 1, true, '2026-11-03 15:12:28.480993+00')
insert into public.modules ("id", "course_id", "title_my", "title_en", "description_my", "description_en", "sort_order", "created_at") values
('1d924239-bc26-4bf6-81fa-521a00cd6d31', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'ဈေးကွက်ချိတ်ဆက်မှုနှင့် ဒစ်ဂျစ်တယ်မားကတ်တင်း', 'Market Linkage & Digital Marketing', 'ဖောက်သည်ရှာဖွေခြင်း၊ ဈေးကွက်ချိတ်ဆက်ခြင်းနှင့် အွန်လိုင်းမြှင့်တင်ရေး။', 'Customer targeting, market linkages and online promotion.', 5, '2026-11-03 15:12:37.325279+00'),
('454b9c23-a2c3-498d-9dce-9af73702bccf', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'ငွေကြေးစီမံခန့်ခွဲမှု', 'Financial Management', 'ငွေသားစီးဆင်းမှု၊ အမြတ်နှင့် ပြန်လည်ရင်းနှီးမြှုပ်နှံမှု။', 'Cash flow, profit and reinvestment planning.', 4, '2026-11-03 15:12:37.325279+00'),
('4910d3a5-5a50-434a-847c-6fef08269a5b', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'အသက်မွေးဝမ်းကျောင်းကို နားလည်ခြင်း', 'Understanding Livelihood', 'မိမိ၏ အသက်မွေးဝမ်းကျောင်းအခြေအနေနှင့် အရင်းအမြစ်များကို သိရှိခြင်း။', 'Understand your livelihood situation and available resources.', 1, '2026-11-03 15:12:37.325279+00'),
('495cc5c0-239a-43a3-a247-50fadd68670f', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'အသက်မွေးဝမ်းကျောင်း လက်တွေ့ကျွမ်းကျင်မှု', 'Vocational Skills', 'ရွေးချယ်ထားသော လက်တွေ့ကျွမ်းကျင်မှုကို လေ့ကျင့်သင်ယူခြင်း။', 'Practice a selected practical vocational skill.', 4, '2026-11-03 15:12:37.325279+00'),
('58ff53b2-8b15-4c7a-83c2-44504778b179', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'လူမှုအသိုင်းအဝိုင်း လိုအပ်ချက်နှင့် အရင်းအမြစ်များ', 'Community Needs & Resources', 'လူမှုအသိုင်းအဝိုင်း၏ လိုအပ်ချက်နှင့် ရရှိနိုင်သော အရင်းအမြစ်များကို လေ့လာခြင်း။', 'Explore community needs and available resources.', 3, '2026-11-03 15:12:37.325279+00'),
('773d4729-7b61-40e4-849f-2650ec61e9b7', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'မိမိကိုယ်ကို သိရှိခြင်းနှင့် ဘဝကျွမ်းကျင်မှု', 'Self-awareness & Life Skills', 'ဆက်သွယ်ရေး၊ အဖွဲ့လိုက်လုပ်ဆောင်မှုနှင့် ကိုယ်ပိုင်ဖွံ့ဖြိုးရေး။', 'Communication, teamwork and personal development.', 2, '2026-11-03 15:12:37.325279+00'),
('8ead850e-df1a-4164-bc6c-a8e9b2fe2cf7', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'အသက်မွေးဝမ်းကျောင်း အကဲဖြတ်ခြင်း', 'Livelihood Assessment', 'လက်ရှိအခြေအနေ၊ ကျွမ်းကျင်မှုနှင့် ဈေးကွက်အခွင့်အလမ်းများကို ပြန်လည်သုံးသပ်ခြင်း။', 'Review current conditions, skills and market opportunities.', 1, '2026-11-03 15:12:37.325279+00'),
('bc2d1832-ad70-41e3-b2cf-2eab098677cc', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'အဆင့်မြင့် လက်တွေ့ကျွမ်းကျင်မှု', 'Advanced Vocational Skills', 'ထုတ်ကုန်အရည်အသွေး၊ ထိရောက်မှုနှင့် ကွဲပြားမှု တိုးတက်စေခြင်း။', 'Improve product quality, efficiency and differentiation.', 2, '2026-11-03 15:12:37.325279+00'),
('c32eb306-17df-4540-9243-7ae8ced7ba82', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'စီးပွားရေးအစီအစဉ် ရေးဆွဲခြင်း', 'Business Planning', 'ဖောက်သည်၊ တန်ဖိုးပေးမှုနှင့် လုပ်ငန်းပုံစံ သတ်မှတ်ခြင်း။', 'Define customers, value proposition and business model.', 3, '2026-11-03 15:12:37.325279+00'),
('d1e9107b-6367-4301-94c8-584933061353', '1b817a4f-ee56-4ce6-b283-64ea8ae6db13', 'ရေရှည်တည်တံ့သော အသက်မွေးဝမ်းကျောင်း ဖွံ့ဖြိုးမှု', 'Sustainable Livelihood Development', 'ရေရှည်လုပ်ငန်းတည်တံ့မှုနှင့် အဆင့်မြင့် လုပ်ငန်းအစီအစဉ်။', 'Plan for long-term sustainability and livelihood growth.', 6, '2026-11-03 15:12:37.325279+00'),
('e0fce07c-a899-4e58-9bc9-17aea1acf037', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'အသက်မွေးဝမ်းကျောင်း စတင်ခြင်း', 'Starting a Livelihood', 'ကိုယ်ပိုင် အသက်မွေးဝမ်းကျောင်း လုပ်ငန်းအစီအစဉ် ရေးဆွဲခြင်း။', 'Develop a simple personal livelihood action plan.', 6, '2026-11-03 15:12:37.325279+00'),
('e48e369d-5d51-42aa-b490-c7f335770640', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'အခြေခံ ငွေကြေးအသိပညာ', 'Basic Financial Literacy', 'ဝင်ငွေ၊ အသုံးစရိတ်၊ စုဆောင်းငွေနှင့် ရိုးရှင်းသော ဘတ်ဂျက်။', 'Income, expenses, savings and simple budgeting.', 5, '2026-11-03 15:12:37.325279+00')
insert into public.lessons ("id", "module_id", "title_my", "title_en", "content_my", "content_en", "resource_path", "video_url", "sort_order", "is_published", "created_at", "content_status", "version_no", "updated_at", "created_by", "reviewed_by", "reviewed_at") values
('09d76db1-7929-49e4-b3f2-6a3704f8f9cb', '495cc5c0-239a-43a3-a247-50fadd68670f', 'လက်တွေ့ကျွမ်းကျင်မှု ရွေးချယ်ခြင်း', 'Choosing a Practical Vocational Skill', 'သင်ခန်းစာရည်ရွယ်ချက်\nမိမိအခြေအနေနှင့် ဒေသတွင်းဈေးကွက်ကို ကိုက်ညီသော ကျွမ်းကျင်မှုတစ်ခု ရွေးချယ်ရန်။\n\nအဓိကအချက်များ\nကျွမ်းကျင်မှုရွေးချယ်ရာတွင် စိတ်ဝင်စားမှု၊ သင်ယူရန်အချိန်၊ ကုန်ကျစရိတ်၊ လိုအပ်သောကိရိယာ၊ ဘေးကင်းရေးနှင့် ဝယ်လိုအားတို့ကို စဉ်းစားပါ။ ဥပမာ အစားအသောက်ပြုပြင်ထုတ်လုပ်မှု၊ အပ်ချုပ်၊ ဖုန်းအခြေခံပြုပြင်မှု၊ စိုက်ပျိုးရေးတန်ဖိုးမြှင့်ခြင်းနှင့် ဒစ်ဂျစ်တယ်ဝန်ဆောင်မှုတို့ ဖြစ်နိုင်သည်။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nစိတ်ဝင်စားသော ကျွမ်းကျင်မှု ၂ ခုကို နှိုင်းယှဉ်ပြီး စတင်သင်ယူရန် လိုအပ်သော ကိရိယာ၊ ကုန်ကျစရိတ်နှင့် သင်ယူနိုင်မည့်နေရာကို စာရင်းပြုစုပါ။', 'Learning objective\nChoose a practical skill that fits your circumstances and local demand.\n\nKey ideas\nConsider interest, learning time, cost, tools, safety and customer demand before choosing a skill. Options may include food processing, tailoring, basic phone repair, value-added agriculture or digital services. Start with a small learning experiment before making a large investment.\n\nPractice\nCompare two skills you are interested in. List the tools, estimated starting costs and possible places where you could learn each skill.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('2621b816-0ee2-4dd3-b365-bf1ac0165034', '773d4729-7b61-40e4-849f-2650ec61e9b7', 'မိမိ၏ အားသာချက်နှင့် ဘဝကျွမ်းကျင်မှုများ', 'Knowing Your Strengths and Life Skills', 'သင်ခန်းစာရည်ရွယ်ချက်\nမိမိ၏ အားသာချက်၊ စိတ်ဝင်စားမှုနှင့် တိုးတက်ရန်လိုအပ်သော ကျွမ်းကျင်မှုများကို ဖော်ထုတ်ရန်။\n\nအဓိကအချက်များ\nမိမိကိုယ်ကို သိရှိခြင်းသည် သင့်တော်သော အလုပ်အကိုင်ရွေးချယ်ရာတွင် အထောက်အကူပြုသည်။ ဆက်သွယ်ပြောဆိုမှု၊ အချိန်စီမံမှု၊ ပြဿနာဖြေရှင်းမှု၊ အဖွဲ့လိုက်လုပ်ဆောင်မှုနှင့် ဆုံးဖြတ်ချက်ချမှုတို့သည် လုပ်ငန်းအမျိုးမျိုးတွင် အသုံးဝင်သော ဘဝကျွမ်းကျင်မှုများဖြစ်သည်။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိကောင်းစွာလုပ်နိုင်သောအရာ ၅ ခု၊ စိတ်ဝင်စားသောအရာ ၃ ခုနှင့် လေ့လာလိုသောကျွမ်းကျင်မှု ၂ ခုကို ရေးပါ။ ယုံကြည်ရသူတစ်ဦးထံမှ မိမိ၏ အားသာချက်တစ်ခုအကြောင်း အကြံပြုချက်တောင်းပါ။', 'Learning objective\nIdentify personal strengths, interests and skills to develop.\n\nKey ideas\nSelf-awareness helps people choose realistic livelihood pathways. Communication, time management, problem-solving, teamwork and decision-making are transferable life skills used in many kinds of work. Strengths can come from formal training, informal experience, household responsibilities or community participation.\n\nPractice\nWrite down five things you can do well, three interests and two skills you want to develop. Ask someone you trust to name one strength they see in you.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('2f28179c-f462-412b-8ae3-d6f85ad44fd9', '4910d3a5-5a50-434a-847c-6fef08269a5b', 'အသက်မွေးဝမ်းကျောင်းဆိုတာ ဘာလဲ။', 'What Is a Livelihood?', 'သင်ခန်းစာရည်ရွယ်ချက်\nအသက်မွေးဝမ်းကျောင်း၏ အဓိပ္ပာယ်နှင့် မိသားစုဘဝအတွက် အရေးပါမှုကို နားလည်ရန်။\n\nအဓိကအချက်များ\nအသက်မွေးဝမ်းကျောင်းဆိုသည်မှာ လူတစ်ဦး သို့မဟုတ် မိသားစုတစ်စုက နေ့စဉ်လိုအပ်ချက်များကို ဖြည့်ဆည်းရန် အသုံးပြုသော ကျွမ်းကျင်မှု၊ အလုပ်အကိုင်၊ ဝင်ငွေ၊ ပိုင်ဆိုင်မှုနှင့် လူမှုကွန်ရက်များ ပေါင်းစပ်ထားခြင်းဖြစ်သည်။ လစာရအလုပ်တစ်ခုတည်းသာ မဟုတ်ပါ။ စိုက်ပျိုးရေး၊ လက်မှုပညာ၊ ဝန်ဆောင်မှုလုပ်ငန်း၊ အသေးစားစီးပွားရေးနှင့် အိမ်တွင်းထုတ်လုပ်မှုတို့လည်း ပါဝင်သည်။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိ သို့မဟုတ် မိသားစု၏ လက်ရှိဝင်ငွေရင်းမြစ် ၃ ခု၊ အသုံးပြုနေသော ကျွမ်းကျင်မှု ၃ ခုနှင့် အရေးကြီးသော အရင်းအမြစ် ၃ ခုကို စာရင်းပြုစုပါ။', 'Learning objective\nUnderstand what a livelihood means and why it matters to household well-being.\n\nKey ideas\nA livelihood is the combination of capabilities, activities, income, assets and social networks that people use to meet their needs. It is broader than a salaried job. Farming, crafts, services, small businesses and home-based production can all be livelihoods. A resilient livelihood can adapt when prices, demand, weather or household circumstances change.\n\nPractice\nList three current income sources, three skills used by you or your household, and three important resources that support your livelihood.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('422a1cf9-42d0-4e70-a677-7e48ebea0172', 'e48e369d-5d51-42aa-b490-c7f335770640', 'ဝင်ငွေ၊ အသုံးစရိတ်နှင့် စုဆောင်းငွေ', 'Income, Expenses and Savings', 'သင်ခန်းစာရည်ရွယ်ချက်\nကိုယ်ပိုင်ငွေကြေးအခြေအနေကို အခြေခံနားလည်ပြီး အသုံးစရိတ်စီမံရန်။\n\nအဓိကအချက်များ\nဝင်ငွေသည် ရရှိသောငွေဖြစ်ပြီး အသုံးစရိတ်သည် သုံးစွဲသောငွေဖြစ်သည်။ မဖြစ်မနေလိုအပ်သော အသုံးစရိတ်နှင့် ရွေးချယ်နိုင်သော အသုံးစရိတ်ကို ခွဲခြားပါ။ ဝင်ငွေမတည်ငြိမ်ပါက နေ့စဉ်မှတ်တမ်းထားခြင်းက ငွေဘယ်နေရာသို့ သွားနေသည်ကို သိစေသည်။ တတ်နိုင်သမျှ ပမာဏငယ်ဖြင့် ပုံမှန်စုဆောင်းခြင်းကို စတင်နိုင်သည်။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nတစ်ပတ်စာ ဝင်ငွေနှင့် အသုံးစရိတ်ကို မှတ်တမ်းတင်ပါ။ လျှော့ချနိုင်သော အသုံးစရိတ်တစ်ခုနှင့် စုဆောင်းရန် ပမာဏငယ်တစ်ခု သတ်မှတ်ပါ။', 'Learning objective\nUnderstand basic personal finance and plan spending.\n\nKey ideas\nIncome is money received; expenses are money spent. Separate essential expenses from optional spending. When income changes from week to week, keeping a simple daily record helps you understand where money goes. Saving can begin with a small, realistic amount set aside regularly.\n\nPractice\nRecord your income and expenses for one week. Identify one expense you could reduce and choose a small savings target that is realistic for you.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('432ff497-7b61-44bf-b28c-039a9dde2c9d', '8ead850e-df1a-4164-bc6c-a8e9b2fe2cf7', 'အသက်မွေးဝမ်းကျောင်း အခြေအနေကို အကဲဖြတ်ခြင်း', 'Assessing a Livelihood Situation', 'သင်ခန်းစာရည်ရွယ်ချက်\nလက်ရှိအသက်မွေးဝမ်းကျောင်း၏ အားသာချက်၊ အားနည်းချက်၊ အခွင့်အလမ်းနှင့် အန္တရာယ်များကို စနစ်တကျ သုံးသပ်ရန်။\n\nအဓိကအချက်များ\nအကဲဖြတ်ရာတွင် မိသားစုဝင်ငွေရင်းမြစ်၊ အရည်အချင်း၊ ပိုင်ဆိုင်မှု၊ ဈေးကွက်၊ ရာသီဥတု၊ လုံခြုံရေးနှင့် အကြွေးအခြေအနေတို့ကို ထည့်သွင်းစဉ်းစားပါ။ အချက်အလက်ကို ခန့်မှန်းမရေးဘဲ ရရှိနိုင်သော အထောက်အထားနှင့် မိသားစုဝင်များ၏ အမြင်ကို စုဆောင်းပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nSWOT ဇယားတစ်ခုဖြင့် မိမိလုပ်ငန်း သို့မဟုတ် မိသားစုအသက်မွေးဝမ်းကျောင်းကို အကဲဖြတ်ပြီး အရေးကြီးဆုံး ပြုပြင်ရန်အချက် ၂ ခုကို ရွေးချယ်ပါ။', 'Learning objective\nAssess livelihood strengths, weaknesses, opportunities and risks.\n\nKey ideas\nReview household income sources, skills, assets, markets, seasonality, safety and debt. Separate evidence from assumptions. Include the perspectives of household members and people who understand the local market. An assessment should lead to practical decisions, not just a list of problems.\n\nPractice\nCreate a SWOT analysis for a livelihood activity and identify the two most important areas for improvement.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('4b35c594-2c69-406d-884b-c9d3128d3b9e', '454b9c23-a2c3-498d-9dce-9af73702bccf', 'ငွေသားစီးဆင်းမှုနှင့် အမြတ်တွက်ချက်ခြင်း', 'Cash Flow and Profit Management', 'သင်ခန်းစာရည်ရွယ်ချက်\nရောင်းအား၊ ကုန်ကျစရိတ်၊ အမြတ်နှင့် ငွေသားစီးဆင်းမှုကို ခွဲခြားနားလည်ရန်။\n\nအဓိကအချက်များ\nရောင်းအားသည် ရောင်းချမှုမှရသော စုစုပေါင်းဝင်ငွေဖြစ်သည်။ အမြတ်သည် ဝင်ငွေမှ ကုန်ကျစရိတ်အားလုံးကို နုတ်ပြီးကျန်သော ပမာဏဖြစ်သည်။ ငွေသားစီးဆင်းမှုသည် ငွေဝင်၊ ငွေထွက် အချိန်ကာလကို ပြသသည်။ စာရင်းကို ပုံမှန်မှတ်တမ်းတင်ပြီး ကိုယ်ပိုင်ငွေနှင့် လုပ်ငန်းငွေကို ခွဲထားပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nထုတ်ကုန်တစ်ခု၏ ရောင်းဈေး၊ တစ်ခုချင်းကုန်ကျစရိတ်နှင့် ရောင်းချမည့်အရေအတွက်ကို အသုံးပြုပြီး အကြမ်းဖျင်းအမြတ်တွက်ပါ။', 'Learning objective\nDistinguish sales, costs, profit and cash flow.\n\nKey ideas\nSales are the total value of goods or services sold. Profit is what remains after all relevant costs are deducted. Cash flow shows when money enters and leaves the business. Keep regular records and separate household money from business money. Include hidden costs such as transport, packaging, utilities and your own time.\n\nPractice\nChoose one product. Record its selling price, unit cost and expected sales quantity, then calculate the estimated gross profit.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('664ff9e1-e77d-4dc9-a08f-641431e5650c', '58ff53b2-8b15-4c7a-83c2-44504778b179', 'လူမှုအသိုင်းအဝိုင်း၏ လိုအပ်ချက်နှင့် အရင်းအမြစ်များ', 'Community Needs and Local Resources', 'သင်ခန်းစာရည်ရွယ်ချက်\nဒေသတွင်း လိုအပ်ချက်များနှင့် ရရှိနိုင်သော အရင်းအမြစ်များကို ချိတ်ဆက်စဉ်းစားရန်။\n\nအဓိကအချက်များ\nအသက်မွေးဝမ်းကျောင်းအခွင့်အလမ်းတစ်ခုသည် လူများ၏ လိုအပ်ချက်ကို ဖြည့်ဆည်းပေးနိုင်ပါက ပိုမိုတည်တံ့နိုင်သည်။ ဒေသတွင်း စားသောက်ကုန်၊ ပြုပြင်ထိန်းသိမ်းရေး၊ သယ်ယူပို့ဆောင်ရေး၊ သင်ကြားရေးနှင့် အိမ်တွင်းဝန်ဆောင်မှုများအတွက် လိုအပ်ချက်ကို လေ့လာပါ။ အရင်းအမြစ်တွင် မြေ၊ ကိရိယာ၊ အချိန်၊ ကျွမ်းကျင်မှု၊ အင်တာနက်နှင့် လူမှုကွန်ရက်များ ပါဝင်နိုင်သည်။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိရပ်ရွာတွင် လူများကြုံတွေ့နေသော ပြဿနာ ၃ ခုနှင့် ဖြေရှင်းရာတွင် အသုံးချနိုင်သော ဒေသတွင်းအရင်းအမြစ် ၃ ခုကို ရေးပါ။', 'Learning objective\nConnect local needs with resources that are already available.\n\nKey ideas\nA livelihood opportunity is more likely to be sustainable when it responds to a real need. Explore demand for food, repairs, transport, tutoring and household services. Local resources may include land, tools, time, skills, internet access, relationships and community spaces. Ask people what they need before investing money.\n\nPractice\nList three problems people experience in your community and three local resources that could help address them.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('a1ca7f5b-eb66-4463-ab3a-2511187d8e87', 'c32eb306-17df-4540-9243-7ae8ced7ba82', 'လုပ်ငန်းအစီအစဉ်၏ အခြေခံအစိတ်အပိုင်းများ', 'Core Elements of a Business Plan', 'သင်ခန်းစာရည်ရွယ်ချက်\nအကောင်အထည်ဖော်နိုင်သော အသေးစားလုပ်ငန်းအစီအစဉ်တစ်ခု ရေးဆွဲရန်။\n\nအဓိကအချက်များ\nလုပ်ငန်းအစီအစဉ်တွင် ဖောက်သည်၊ ဖြေရှင်းပေးမည့်လိုအပ်ချက်၊ ထုတ်ကုန်/ဝန်ဆောင်မှု၊ ဈေးနှုန်း၊ ရောင်းချမည့်လမ်းကြောင်း၊ လုပ်ငန်းလည်ပတ်မှု၊ ကုန်ကျစရိတ်နှင့် ဝင်ငွေခန့်မှန်းချက်တို့ ပါဝင်သည်။ အချက်အလက်မသေချာပါက ခန့်မှန်းချက်ဟု မှတ်သားပြီး ဖောက်သည်နှင့် ဈေးကွက်ထံမှ စမ်းသပ်အတည်ပြုပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nစာမျက်နှာတစ်မျက်နှာစာ လုပ်ငန်းအစီအစဉ်ရေးပြီး အဓိကယူဆချက် ၂ ခုကို ဘယ်လိုစမ်းသပ်မည်ကို ဖော်ပြပါ။', 'Learning objective\nPrepare a practical one-page plan for a small enterprise.\n\nKey ideas\nA business plan describes customers, the need being addressed, products or services, pricing, sales channels, operations, costs and expected income. Mark uncertain figures as estimates. Test key assumptions with potential customers before making large commitments.\n\nPractice\nDraft a one-page business plan and explain how you will test two important assumptions about customer demand or costs.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('c83887e6-8c8a-4070-b251-f1d25718af73', 'd1e9107b-6367-4301-94c8-584933061353', 'ရေရှည်တည်တံ့ပြီး ခံနိုင်ရည်ရှိသော လုပ်ငန်း', 'Building a Sustainable and Resilient Livelihood', 'သင်ခန်းစာရည်ရွယ်ချက်\nပြောင်းလဲမှုများကို ခံနိုင်ရည်ရှိပြီး လူမှုနှင့် ပတ်ဝန်းကျင်အပေါ် တာဝန်ယူသော လုပ်ငန်းတစ်ခု စီမံရန်။\n\nအဓိကအချက်များ\nရေရှည်တည်တံ့မှုတွင် ငွေကြေးအကျိုးအမြတ်သာမက လူမှုအကျိုးသက်ရောက်မှု၊ ပတ်ဝန်းကျင်ထိခိုက်မှုနှင့် လုပ်ငန်းဆက်လက်လည်ပတ်နိုင်မှုတို့ ပါဝင်သည်။ ဝင်ငွေရင်းမြစ်တစ်ခုတည်းအပေါ် မမှီခိုရန်၊ အရေးပေါ်အစီအစဉ်ထားရန်၊ စွန့်ပစ်ပစ္စည်းလျှော့ချရန်နှင့် အလုပ်သမား/ဖောက်သည်များကို မျှတစွာဆက်ဆံရန် စဉ်းစားပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိလုပ်ငန်းအတွက် ဖြစ်နိုင်သော အန္တရာယ် ၃ ခု၊ ကြိုတင်ကာကွယ်ရေးနည်းလမ်း ၃ ခုနှင့် ပတ်ဝန်းကျင်ထိခိုက်မှု လျှော့ချမည့် လုပ်ဆောင်ချက် ၂ ခုကို ရေးပါ။', 'Learning objective\nPlan a livelihood that can adapt to change and considers social and environmental responsibility.\n\nKey ideas\nSustainability includes financial viability, social impact, environmental effects and the ability to continue operating. Avoid depending on one income source where possible. Prepare for disruptions, reduce waste, use resources carefully and treat workers and customers fairly. Review risks regularly as conditions change.\n\nPractice\nList three risks to your livelihood activity, three ways to reduce those risks and two actions that could reduce environmental impact.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('d0e43b3e-437b-4153-91d2-69f9b1dac47a', 'bc2d1832-ad70-41e3-b2cf-2eab098677cc', 'အရည်အသွေးနှင့် ထုတ်လုပ်မှုစံနှုန်း', 'Quality and Standards in Vocational Work', 'သင်ခန်းစာရည်ရွယ်ချက်\nထုတ်ကုန် သို့မဟုတ် ဝန်ဆောင်မှု၏ အရည်အသွေးကို တည်ငြိမ်စေရန် အခြေခံစံနှုန်းများ သတ်မှတ်ရန်။\n\nအဓိကအချက်များ\nအရည်အသွေးဆိုသည်မှာ ဖောက်သည်မျှော်လင့်ချက်နှင့် သဘောတူထားသော စံနှုန်းကို ဖြည့်ဆည်းပေးနိုင်ခြင်းဖြစ်သည်။ လုပ်ငန်းစဉ်အဆင့်တိုင်းတွင် စစ်ဆေးချက်ထားပါ။ သန့်ရှင်းရေး၊ ကိရိယာထိန်းသိမ်းမှု၊ အလုပ်ခွင်ဘေးကင်းရေး၊ အချိန်မီပေးပို့မှုနှင့် ဖောက်သည်တုံ့ပြန်ချက်တို့ကို ပုံမှန်စောင့်ကြည့်ပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိထုတ်ကုန် သို့မဟုတ် ဝန်ဆောင်မှုအတွက် စစ်ဆေးရမည့် အရည်အသွေးအချက် ၅ ချက်ပါ checklist တစ်ခု ပြုလုပ်ပါ။', 'Learning objective\nSet basic standards to deliver consistent product or service quality.\n\nKey ideas\nQuality means meeting agreed standards and customer expectations. Add simple checks at each stage of work. Monitor cleanliness, tool maintenance, workplace safety, on-time delivery and customer feedback. Document a repeatable process so quality does not depend only on memory.\n\nPractice\nCreate a five-point quality checklist for a product or service you provide or plan to provide.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('f0a3dd51-47e1-4362-9d9a-a5ec1ff27001', '1d924239-bc26-4bf6-81fa-521a00cd6d31', 'ဈေးကွက်လေ့လာခြင်းနှင့် ဒစ်ဂျစ်တယ်မားကတ်တင်း', 'Market Research and Digital Marketing', 'သင်ခန်းစာရည်ရွယ်ချက်\nဖောက်သည်လိုအပ်ချက်ကို လေ့လာပြီး သင့်တော်သော အရောင်းမြှင့်တင်ရေးနည်းလမ်း ရွေးချယ်ရန်။\n\nအဓိကအချက်များ\nဈေးကွက်လေ့လာရာတွင် ဖောက်သည်ဘယ်သူလဲ၊ ဘာလိုအပ်လဲ၊ လက်ရှိဘယ်ကဝယ်ယူလဲ၊ ဘယ်ဈေးနှုန်းကို လက်ခံနိုင်လဲဆိုသည်ကို မေးမြန်းပါ။ ဒစ်ဂျစ်တယ်မားကတ်တင်းတွင် မှန်ကန်သောထုတ်ကုန်ဓာတ်ပုံ၊ ရှင်းလင်းသောဖော်ပြချက်၊ ဈေးနှုန်းနှင့် ဆက်သွယ်ရန်နည်းလမ်း ထည့်ပါ။ ကိုယ်ရေးအချက်အလက်နှင့် ဖောက်သည်ခွင့်ပြုချက်ကို လေးစားပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nဖြစ်နိုင်သော ဖောက်သည် ၅ ဦးထံမှ မေးခွန်း ၃ ခုဖြင့် တုံ့ပြန်ချက်စုဆောင်းပြီး လူမှုကွန်ရက်ပို့စ်တစ်ခု ရေးဆွဲပါ။', 'Learning objective\nResearch customer needs and choose suitable ways to promote an offer.\n\nKey ideas\nAsk who the customers are, what they need, where they currently buy and what price they can accept. Digital marketing content should include a clear product photo, honest description, price and contact method. Respect customer privacy, consent and platform rules. Track which messages lead to genuine enquiries and sales.\n\nPractice\nCollect feedback from five potential customers using three questions. Draft one social media post based on what you learned.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null),
('f3f73cba-30e9-42d8-b954-f4d0a60d1761', 'e0fce07c-a899-4e58-9bc9-17aea1acf037', 'အသေးစားအသက်မွေးဝမ်းကျောင်း စတင်ခြင်း', 'Starting a Small Livelihood Activity', 'သင်ခန်းစာရည်ရွယ်ချက်\nအန္တရာယ်နည်းသော စမ်းသပ်မှုတစ်ခုဖြင့် အသက်မွေးဝမ်းကျောင်းလုပ်ငန်း စတင်ရန်။\n\nအဓိကအချက်များ\nလုပ်ငန်းမစတင်မီ မည်သူ့အတွက် ဘာဝန်ဆောင်မှု သို့မဟုတ် ထုတ်ကုန်ပေးမည်ကို ရှင်းလင်းပါ။ အရင်းအနှီးအားလုံးကို တစ်ခါတည်း မသုံးဘဲ သေးငယ်သော စမ်းသပ်ထုတ်လုပ်မှု သို့မဟုတ် ဝန်ဆောင်မှုဖြင့် စတင်ပါ။ ဖောက်သည်၏ တုံ့ပြန်ချက်ကို နားထောင်ပြီး အရည်အသွေး၊ ဈေးနှုန်းနှင့် ပို့ဆောင်ပေးပုံကို ပြုပြင်ပါ။\n\nလက်တွေ့လေ့ကျင့်ခန်း\nမိမိစတင်လိုသော လုပ်ငန်းအကြံဉာဏ်တစ်ခုအတွက် ဖောက်သည်အုပ်စု၊ ပေးမည့်တန်ဖိုး၊ လိုအပ်သောအရင်းအမြစ်နှင့် ပထမဆုံးစမ်းသပ်မည့်အဆင့်ကို ရေးဆွဲပါ။', 'Learning objective\nStart a livelihood activity through a small, low-risk test.\n\nKey ideas\nBe clear about who you will serve and what product or service you will provide. Avoid spending all available capital at once. Begin with a small test, listen to customer feedback and improve quality, pricing and delivery. Keep simple records of costs and sales from the beginning.\n\nPractice\nFor one livelihood idea, identify the target customers, the value you will offer, the resources required and one small test you can conduct first.', null, null, 1, true, '2026-11-03 15:23:48.838648+00', 'published', 1, '2026-11-03 16:29:04.042368+00', null, null, null)
insert into public.quizzes ("id", "course_id", "title_my", "title_en", "pass_mark", "is_published", "created_at") values
('3470e51c-fa25-41f3-9998-b22e5088a29b', '7f377790-81fe-4b86-bed5-0ea8e1990586', 'BASIC အဆင့် အသိပညာ စစ်ဆေးမှု', 'BASIC Level Knowledge Check', 70.00, false, '2026-11-03 15:41:44.660575+00')
insert into public.quiz_questions ("id", "quiz_id", "question_my", "question_en", "options", "sort_order") values
('0520e738-33b0-4220-92e6-09f44a3f24fa', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အသက်မွေးဝမ်းကျောင်း (Livelihood) ဆိုသည်မှာ မည်သည့်အရာကို အဓိကဆိုလိုသနည်း။', 'What does livelihood mainly refer to?', '[{"en":"Only one job for earning income","my":"ဝင်ငွေရရှိရန် အလုပ်တစ်ခုတည်း"},{"en":"The capabilities, assets, activities and resources people use to make a living","my":"လူတစ်ဦး သို့မဟုတ် မိသားစု၏ ဘဝရပ်တည်ရေးအတွက် အသုံးပြုသော စွမ်းရည်၊ ပိုင်ဆိုင်မှု၊ လုပ်ငန်းများနှင့် အရင်းအမြစ်များ"},{"en":"A large business","my":"စီးပွားရေးလုပ်ငန်းကြီးတစ်ခု"},{"en":"A type of government subsidy","my":"အစိုးရထောက်ပံ့ကြေးတစ်မျိုး"}]'::jsonb, 1),
('1ad819c4-8aa7-41ad-8a8a-f95f5a6af049', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'ဝင်ငွေနှင့် အသုံးစရိတ်ကို မှတ်တမ်းတင်ခြင်း၏ အဓိကရည်ရွယ်ချက်မှာ အဘယ်နည်း။', 'What is the main purpose of recording income and expenses?', '[{"en":"Only to estimate spending","my":"ငွေသုံးစွဲမှုကို ခန့်မှန်းရုံသာ ပြုလုပ်ရန်"},{"en":"To understand the financial situation and manage it better","my":"ငွေကြေးအခြေအနေကို သိရှိပြီး ပိုမိုကောင်းမွန်စွာ စီမံနိုင်ရန်"},{"en":"To increase expenses","my":"အသုံးစရိတ်ကို တိုးမြှင့်ရန်"},{"en":"To find reasons to borrow","my":"အကြွေးယူရန် အကြောင်းပြချက်ရှာရန်"}]'::jsonb, 6),
('31efd083-3e67-4a8e-8cd3-d9c756cb544d', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အမြတ် (Profit) ကို အခြေခံအားဖြင့် မည်သို့တွက်ချက်သနည်း။', 'How is profit basically calculated?', '[{"en":"Income + expenses","my":"ဝင်ငွေ + ကုန်ကျစရိတ်"},{"en":"Expenses − income","my":"ကုန်ကျစရိတ် − ဝင်ငွေ"},{"en":"Income − expenses","my":"ဝင်ငွေ − ကုန်ကျစရိတ်"},{"en":"Sales × expenses","my":"ရောင်းရငွေ × ကုန်ကျစရိတ်"}]'::jsonb, 7),
('43183382-7745-4281-8635-bfe6f34e753a', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အသက်မွေးဝမ်းကျောင်း ကျွမ်းကျင်မှုတစ်ခုကို ရွေးချယ်ရာတွင် မည်သည့်အချက်များကို ထည့်သွင်းစဉ်းစားသင့်သနည်း။', 'What should be considered when choosing a vocational skill?', '[{"en":"Personal interest and market demand","my":"မိမိစိတ်ဝင်စားမှုနှင့် ဈေးကွက်လိုအပ်ချက်"},{"en":"Only the course title","my":"သင်တန်းအမည်သာ"},{"en":"Only a friend’s choice","my":"မိတ်ဆွေတစ်ဦး၏ ရွေးချယ်မှုသာ"},{"en":"Only the cost","my":"ကုန်ကျစရိတ်ကိုသာ"}]'::jsonb, 5),
('5f47329d-e831-40e7-8052-986f2374e3ef', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'ကိုယ့်ကိုယ်ကို အားသာချက်၊ စိတ်ဝင်စားမှုနှင့် ကျွမ်းကျင်မှုများကို သိရှိခြင်းက ဘာကြောင့် အရေးကြီးသနည်း။', 'Why is it important to understand your strengths, interests and skills?', '[{"en":"So you can only choose the same work as others","my":"အခြားသူများနှင့် တူညီသောအလုပ်ကိုသာ ရွေးချယ်နိုင်ရန်"},{"en":"To choose a livelihood pathway that fits you","my":"မိမိနှင့် ကိုက်ညီသော အသက်မွေးဝမ်းကျောင်းလမ်းကြောင်းကို ရွေးချယ်ရန်"},{"en":"To stop learning","my":"လေ့လာမှုကို ရပ်တန့်ရန်"},{"en":"To ensure there will be no challenges","my":"အခက်အခဲများ မရှိတော့စေရန်"}]'::jsonb, 3),
('75554836-9f76-4e71-ac94-e13cf81765e9', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'ရေရှည်တည်တံ့သော အသက်မွေးဝမ်းကျောင်းတစ်ခု၏ အရေးကြီးသော လက္ခဏာမှာ မည်သည့်အရာဖြစ်သနည်း။', 'Which is an important feature of a sustainable livelihood?', '[{"en":"Getting the highest income in the shortest time","my":"အချိန်တိုအတွင်း ဝင်ငွေအများဆုံးရခြင်း"},{"en":"Depending only on other people’s resources","my":"အခြားသူများ၏ အရင်းအမြစ်များကိုသာ မှီခိုခြင်း"},{"en":"Coping with challenges without undermining future resources","my":"အခက်အခဲများကို ရင်ဆိုင်နိုင်ပြီး အနာဂတ်အတွက် အရင်းအမြစ်များကို မထိခိုက်စေခြင်း"},{"en":"Ignoring all risks","my":"အန္တရာယ်အားလုံးကို လျစ်လျူရှုခြင်း"}]'::jsonb, 2),
('8be9892d-a5a9-4301-a86a-1cfce8e032cc', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'လူမှုအသိုင်းအဝိုင်း၏ လိုအပ်ချက်များကို လေ့လာရာတွင် မည်သည့်နည်းလမ်းက ပိုမိုသင့်လျော်သနည်း။', 'Which approach is more suitable for understanding community needs?', '[{"en":"Relying only on your own assumptions","my":"မိမိထင်မြင်ချက်တစ်ခုတည်းကို အခြေခံခြင်း"},{"en":"Listening to only a few selected voices","my":"လူအနည်းငယ်၏ အမြင်ကိုသာ နားထောင်ခြင်း"},{"en":"Asking, listening and gathering available information","my":"မေးမြန်းခြင်း၊ နားထောင်ခြင်းနှင့် ရရှိနိုင်သော အချက်အလက်များကို စုဆောင်းခြင်း"},{"en":"Deciding the needs in advance","my":"လိုအပ်ချက်များကို ကြိုတင်ဆုံးဖြတ်ထားခြင်း"}]'::jsonb, 4),
('94a2df03-2734-4b7b-b794-fba86014d6d9', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အသေးစားလုပ်ငန်းတစ်ခု မစတင်မီ မည်သည့်အရာကို ဦးစွာလေ့လာသင့်သနည်း။', 'What should be researched before starting a small business?', '[{"en":"Customer needs, competitors and market conditions","my":"ဖောက်သည်လိုအပ်ချက်၊ ပြိုင်ဘက်နှင့် ဈေးကွက်အခြေအနေ"},{"en":"Only the business name","my":"လုပ်ငန်းအမည်ကိုသာ"},{"en":"Only another business’s profit","my":"အခြားလုပ်ငန်းတစ်ခု၏ အမြတ်ကိုသာ"},{"en":"Only the advertising design","my":"ကြော်ငြာပုံစံကိုသာ"}]'::jsonb, 8),
('af7d8358-8c69-4e88-8d02-7ab744c77fa4', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အသက်မွေးဝမ်းကျောင်းလုပ်ငန်းတစ်ခုကို စတင်ပြီးနောက် မည်သည့်အရာကို ပုံမှန်ပြန်လည်သုံးသပ်သင့်သနည်း။', 'What should be reviewed regularly after starting a livelihood activity?', '[{"en":"Only the business name","my":"လုပ်ငန်းအမည်တစ်ခုတည်း"},{"en":"Profit, costs, customer feedback and progress toward goals","my":"အမြတ်၊ ကုန်ကျစရိတ်၊ ဖောက်သည်တုံ့ပြန်မှုနှင့် ရည်မှန်းချက်တိုးတက်မှု"},{"en":"Only the start date","my":"စတင်သည့်နေ့စွဲသာ"},{"en":"Only competitors’ social media posts","my":"ပြိုင်ဘက်များ၏ လူမှုကွန်ရက်ပို့စ်များသာ"}]'::jsonb, 10),
('fc3341ad-a7ee-4f48-9abd-9453e59b96c5', '3470e51c-fa25-41f3-9998-b22e5088a29b', 'အသက်မွေးဝမ်းကျောင်းလုပ်ငန်းတစ်ခုတွင် အန္တရာယ် (Risk) ကို လျှော့ချရန် မည်သည့်လုပ်ဆောင်ချက်က သင့်လျော်သနည်း။', 'Which action is appropriate for reducing livelihood risks?', '[{"en":"Preparing contingency plans and savings for emergencies","my":"အရေးပေါ်အခြေအနေများအတွက် ကြိုတင်အစီအစဉ်နှင့် စုဆောင်းငွေထားရှိခြင်း"},{"en":"Depending on only one income source","my":"ဝင်ငွေရင်းမြစ်တစ်ခုတည်းကိုသာ မှီခိုခြင်း"},{"en":"Investing without checking information","my":"အချက်အလက်မစစ်ဆေးဘဲ ရင်းနှီးမြှုပ်နှံခြင်း"},{"en":"Keeping no expense records","my":"ကုန်ကျစရိတ်မှတ်တမ်း မထားခြင်း"}]'::jsonb, 9)
